#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

// Function to print mode in octal format
void print_octal_mode(mode_t m) {
    printf("0%o", m & 0777);
}

int main(void) {
    mode_t default_mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP | S_IROTH | S_IWOTH; // 0666
    mode_t new_umask = 0077; // Deny all permissions for group and others
    mode_t old_mask;

    // 1. Retrieve the original umask and set a temporary (or new) umask
    old_mask = umask(new_umask);

    printf("Previous umask was: ");
    print_octal_mode(old_mask);
    printf("\n");

    printf("New umask is set to: ");
    print_octal_mode(new_umask);
    printf("\n");

    // 2. Create a file. Requested mode 0666.
    // Actual mode will be 0666 & ~0077 = 0600 (rw-------)
    int fd = open("test_file_umask.txt", O_CREAT | O_WRONLY, default_mode);

    if (fd == -1) {
        perror("open failed");
        // Restore umask before exit if open fails
        umask(old_mask);
        return EXIT_FAILURE;
    }
    close(fd);

    printf("Created 'test_file_umask.txt'. Check its mode (expected 0600).\n");

    // 3. Restore the original umask
    umask(old_mask);

    return EXIT_SUCCESS;
}
